from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np
lines=open('initial.xyz').read().splitlines()[2:];els=[l.split()[0] for l in lines];xyz=np.array([[float(x) for x in l.split()[1:]] for l in lines]);
m=Chem.RWMol()
for e in els[4:]:
 a=Chem.Atom(e);a.SetNoImplicit(True);m.AddAtom(a)
for k in range(4):
 b=k*32
 m.GetAtomWithIdx(b+2).SetFormalCharge(-1)
 def bond(i,j,order=Chem.BondType.SINGLE):m.AddBond(b+i,b+j,order)
 bond(0,1,Chem.BondType.DOUBLE);bond(1,2)
 for c,h in [(0,3),(1,4),(2,5)]:bond(c,h)
 bond(0,6);bond(2,19)
 for s in [6,19]:
  for cm in [s+1,s+5,s+9]:
   bond(s,cm)
   for h in range(cm+1,cm+4):bond(cm,h)
m=m.GetMol();Chem.SanitizeMol(m)
conf=Chem.Conformer(128)
for i,p in enumerate(xyz[4:]):conf.SetAtomPosition(i,p)
m.AddConformer(conf)
print('UFF params',AllChem.UFFHasAllMoleculeParams(m))
f=AllChem.UFFGetMoleculeForceField(m,ignoreInterfragInteractions=False)
cp=[f.AddExtraPoint(*[float(x) for x in p],fixed=True)-1 for p in xyz[:4]]
for k in range(4):
 b=k*32
 for ci,a,d in [(k,b,2.15),(k,b+1,2.2),((k+1)%4,b+2,1.98)]:f.UFFAddDistanceConstraint(cp[ci],a,False,d,d,100)
 f.UFFAddAngleConstraint(b+1,b+2,cp[(k+1)%4],False,105,115,50)
 # Maintain the depicted raised allyl central carbon, and keep core near its start.
 for a in [b,b+1,b+2]:f.UFFAddPositionConstraint(a,0.4,20)
f.Initialize()
print('initial energy',f.CalcEnergy());print('minimize',f.Minimize(maxIts=3000));print('final energy',f.CalcEnergy())
xyz[4:]=np.array(conf.GetPositions())
with open('preoptimized.xyz','w') as out:
 out.write('132\nBis(trimethylsilyl)allylcopper tetramer, explicit H\n')
 for e,p in zip(els,xyz):out.write(f'{e} {p[0]:.9f} {p[1]:.9f} {p[2]:.9f}\n')
Chem.MolToMolFile(m,'ligands.mol')
